from __future__ import annotations

from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse

from .esp_niche import require_esp_social_member

router = APIRouter()


@router.get(
    "/command-center/social/provider-analytics",
    response_class=HTMLResponse,
    include_in_schema=False,
)
def provider_analytics_portal(request: Request):
    _member, membership, profile = require_esp_social_member(request)
    definition = profile["catalog"]
    accent = escape(definition["theme"]["accent"])
    secondary = escape(definition["theme"]["secondary"])
    niche = escape(definition["title"])
    role = membership.get("roles") or (
        "owner" if membership.get("status") == "owner" else "member"
    )

    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><meta name='robots' content='noindex,nofollow'><meta name='theme-color' content='#05040b'><title>ESP Provider Analytics</title><style>
:root{--accent:__ACCENT__;--secondary:__SECONDARY__;--bg:#03040a;--panel:#0d0f1b;--line:#ffffff1c;--text:#fff;--muted:#b7bbce;--green:#79e3a8;--amber:#ffd36b;--red:#ff8f9d;--cyan:#5ce8ff}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:radial-gradient(circle at 8% 0,var(--secondary),transparent 29%),radial-gradient(circle at 92% 4%,var(--accent),transparent 23%),linear-gradient(#03040a,#070811 65%,#020309)}a{color:inherit;text-decoration:none}button,select{font:inherit}.wrap{width:min(1320px,calc(100% - 28px));margin:auto}.nav{position:sticky;top:0;z-index:10;background:#05060bee;backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.navin{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:14px}.brand{font-weight:950}.brand small{display:block;color:var(--accent);font-size:.64rem;text-transform:uppercase;letter-spacing:.08em}.actions{display:flex;gap:7px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:12px;padding:9px 12px;font-weight:850;cursor:pointer}.btn.primary{border:0;background:linear-gradient(115deg,var(--accent),var(--secondary));color:#130b18}.btn:disabled{opacity:.43;cursor:not-allowed}.hero{padding:42px 0 20px}.eyebrow{color:var(--accent);font-size:.72rem;font-weight:950;letter-spacing:.17em;text-transform:uppercase}.hero h1{font-size:clamp(2.5rem,6vw,4.8rem);letter-spacing:-.05em;line-height:.95;margin:.14em 0 .2em}.hero h1 span{background:linear-gradient(95deg,#fff,var(--accent),var(--secondary));background-clip:text;color:transparent}.lead{color:var(--muted);max-width:1000px;line-height:1.62}.toolbar,.truth,.panel,.provider{border:1px solid var(--line);background:linear-gradient(145deg,#101323e8,#080a14f0);border-radius:20px;padding:14px}.toolbar{display:grid;grid-template-columns:1fr auto;gap:9px;align-items:center;margin-bottom:12px}.field{width:100%;border:1px solid var(--line);background:#070913;color:#fff;border-radius:11px;padding:10px}.truth{margin-bottom:12px;color:#dffaff;border-color:#5ce8ff38}.providers{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;margin-bottom:12px}.provider{display:flex;flex-direction:column;gap:10px;min-height:250px}.provider h2{margin:0}.head{display:flex;gap:10px;align-items:flex-start}.icon{width:44px;height:44px;border:1px solid var(--line);background:#ffffff08;border-radius:13px;display:grid;place-items:center;font-size:1.35rem}.status{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:5px 8px;font-size:.69rem;font-weight:900;text-transform:uppercase;letter-spacing:.04em}.status.ready{color:var(--green);border-color:#79e3a850}.status.blocked,.status.not_connected{color:var(--red);border-color:#ff8f9d55}.status.adapter_pending{color:var(--amber);border-color:#ffd36b55}.muted{color:var(--muted)}.small{font-size:.72rem;line-height:1.48}.provider .btn{margin-top:auto}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:12px}.metric{border:1px solid var(--line);border-radius:15px;padding:13px;background:#ffffff05}.metric b{display:block;font-size:1.4rem}.snapshot{display:grid;grid-template-columns:1.3fr .8fr .8fr .8fr;gap:9px;align-items:center;border:1px solid var(--line);background:#ffffff04;border-radius:14px;padding:11px;margin:8px 0}.snapshot strong{display:block}.notice{display:none;border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-bottom:12px}.notice.show{display:block}.notice.error{color:#ffd6dc;border-color:#ff8f9d50}.empty{border:1px dashed #ffffff2a;border-radius:16px;padding:24px;text-align:center;color:var(--muted)}.footer{border-top:1px solid var(--line);padding:28px 0 40px;margin-top:32px;color:var(--muted);font-size:.84rem}@media(max-width:930px){.providers{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}.snapshot{grid-template-columns:1fr 1fr}}@media(max-width:620px){.toolbar,.metrics,.snapshot{grid-template-columns:1fr}.actions .optional{display:none}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/command-center'>Elevate Souls Productions<small>Private Creator & Agent Hub · Provider Analytics</small></a><div class='actions'><a class='btn primary' href='/command-center/social'>Social Management</a><a class='btn optional' href='/command-center/social/connections'>Connections</a><a class='btn optional' href='/command-center/social-insights'>Aura Insights</a></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>__NICHE__ · __ROLE__ · Authorised performance data</div><h1>Provider stats into <span>Aura Intelligence.</span></h1><p class='lead'>Sync only statistics that an approved ESP member has explicitly authorised. YouTube owned-channel video statistics are active in this stage. TikTok and Instagram stay visibly blocked or pending until the additional provider permission path is deliberately enabled. No OAuth token is returned to this page.</p></section><div id='notice' class='notice'></div><section class='toolbar'><select id='space' class='field' aria-label='Social House'></select><button class='btn' onclick='reloadAll()'>Reload</button></section><section class='truth' id='truth'>Loading provider capabilities…</section><section class='providers' id='providers'></section><section class='metrics' id='metrics'></section><section class='panel'><div style='display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap'><div><div class='eyebrow'>Aura analytics store</div><h2 style='margin:4px 0'>Latest provider snapshots</h2></div><a class='btn' href='/command-center/social-insights'>Open full Aura Insights</a></div><div id='snapshots' class='empty'>Choose a Social House.</div></section></main><footer class='footer'><div class='wrap'><strong>Elevate Souls Productions</strong> · Private ESP Creator & Agent Social Management · Powered by Aura AI Systems</div></footer><script>
const SOCIAL='/command-center/api/social',INTEL='/command-center/api/social-intelligence';const $=id=>document.getElementById(id);let caps={},snapshots=[];const PROVIDERS={youtube:{label:'YouTube',icon:'▶️'},tiktok:{label:'TikTok',icon:'🎵'},instagram:{label:'Instagram',icon:'📸'}};const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function notice(m,b=false){const n=$('notice');n.textContent=m;n.className='notice show'+(b?' error':'');clearTimeout(window._n);window._n=setTimeout(()=>n.className='notice',6500)}async function req(base,path,opt={}){const r=await fetch(base+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch(_){}if(!r.ok){const d=b.detail;const msg=typeof d==='string'?d:(d?.reason||d?.message||`Request failed (${r.status})`);throw new Error(msg)}return b}function pretty(v){return String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}function metric(label,value){return `<div class="metric"><b>${esc(value)}</b><span class="muted small">${esc(label)}</span></div>`}function renderCaps(){ $('truth').textContent=caps.truthful_state||'Provider analytics capability is permission-bound.';$('providers').innerHTML=Object.entries(PROVIDERS).map(([name,spec])=>{const c=caps[name]||{status:'not_connected',ready:false,reason:'Not available.'};const scopes=(c.required_scopes||[]).length?`Required: ${(c.required_scopes||[]).map(esc).join(', ')}`:'No additional scope is claimed by this stage.';return `<article class="provider"><div class="head"><div class="icon">${spec.icon}</div><div><h2>${esc(spec.label)}</h2><span class="status ${esc(c.status)}">${esc(pretty(c.status))}</span></div></div><div class="muted small">${esc(c.reason)}</div><div class="muted small">${scopes}</div>${c.account_label?`<div class="small"><b>${esc(c.account_label)}</b></div>`:''}<button class="btn ${c.ready?'primary':''}" ${c.ready?'':'disabled'} onclick="sync('${esc(name)}')">${c.ready?'Sync '+esc(spec.label):'Sync unavailable'}</button></article>`}).join('') }function renderSnapshots(){const providerRows=snapshots.filter(x=>['youtube','tiktok','instagram'].includes(x.platform));const views=providerRows.reduce((n,x)=>n+Number(x.metrics?.views||0),0),likes=providerRows.reduce((n,x)=>n+Number(x.metrics?.likes||0),0),comments=providerRows.reduce((n,x)=>n+Number(x.metrics?.comments||0),0);$('metrics').innerHTML=metric('Provider snapshots',providerRows.length)+metric('Views in synced snapshots',views.toLocaleString())+metric('Likes in synced snapshots',likes.toLocaleString())+metric('Comments in synced snapshots',comments.toLocaleString());if(!providerRows.length){$('snapshots').className='empty';$('snapshots').textContent='No official provider snapshots have been synced yet.';return}$('snapshots').className='';$('snapshots').innerHTML=providerRows.slice(0,50).map(x=>`<div class="snapshot"><div><strong>${esc(x.period_label||x.source_ref||x.platform)}</strong><div class="muted small">${esc(x.platform)} · ${esc(x.source_ref||'manual/provider snapshot')}</div></div><div><b>${Number(x.metrics?.views||0).toLocaleString()}</b><div class="muted small">Views</div></div><div><b>${Number(x.metrics?.likes||0).toLocaleString()}</b><div class="muted small">Likes</div></div><div><b>${Number(x.metrics?.comments||0).toLocaleString()}</b><div class="muted small">Comments</div></div></div>`).join('')}async function loadSpace(){const id=$('space').value;if(!id)return;try{const [c,a]=await Promise.all([req(SOCIAL,`/spaces/${encodeURIComponent(id)}/provider-analytics/capabilities`),req(INTEL,`/spaces/${encodeURIComponent(id)}/analytics`)]);caps=c;snapshots=a.snapshots||[];renderCaps();renderSnapshots()}catch(e){notice(e.message,true)}}async function reloadAll(){try{const d=await req(SOCIAL,'/spaces');const rows=d.spaces||[],current=$('space').value;$('space').innerHTML=rows.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');if(current&&rows.some(x=>x.id===current))$('space').value=current;$('space').onchange=loadSpace;if(rows.length)await loadSpace();else{$('truth').textContent='Create a Social House before syncing provider statistics.';$('providers').innerHTML='<div class="empty">No Social Houses yet.</div>';$('metrics').innerHTML='';$('snapshots').className='empty';$('snapshots').textContent='No Social Houses yet.'}}catch(e){notice(e.message,true)}}async function sync(provider){const id=$('space').value,c=caps[provider];if(!id)return notice('Choose a Social House first.',true);if(!c?.ready)return notice(c?.reason||'This provider is not ready for analytics sync.',true);try{const d=await req(SOCIAL,`/spaces/${encodeURIComponent(id)}/provider-analytics/${encodeURIComponent(provider)}/sync`,{method:'POST'});notice(d.detail||`${PROVIDERS[provider]?.label||provider} statistics synced.`);await loadSpace()}catch(e){notice(e.message,true)}}reloadAll();
</script></body></html>"""
    return HTMLResponse(
        html.replace("__ACCENT__", accent)
        .replace("__SECONDARY__", secondary)
        .replace("__NICHE__", niche)
        .replace("__ROLE__", escape(str(role).replace("both", "Creator + Agent").title()))
    )


__all__ = ["router"]
